require __DIR__.'/../includes/bootstrap.php';$farmer=require_login('farmer');if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: /farmer/dashboard.php');exit;}verify_csrf();$id=filter_var($_POST['order_id']??null,FILTER_VALIDATE_INT);$new=$_POST['status']??'';
try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM orders WHERE id=? AND farmer_id=? FOR UPDATE');$q->execute([$id,$farmer['id']]);$order=$q->fetch();$allowed=['new'=>['accepted','rejected'],'accepted'=>['ready'],'ready'=>['completed']];if(!$order||!in_array($new,$allowed[$order['status']]??[],true)){throw new RuntimeException('That order can no longer be changed.');}$q=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$q->execute([$new,$id]);if($new==='rejected'){$q=$pdo->prepare("UPDATE products SET quantity=quantity+?, status=IF(status='sold_out','active',status) WHERE id=?");$q->execute([$order['quantity'],$order['product_id']]);}$pdo->commit();flash('Order updated to '.str_replace('_',' ',$new).'.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Could not update the order.','error');}header('Location: /farmer/dashboard.php');exit;
